   40: /**
   41:  * @brief Handles pet action bar commands, reactions, and spell casts.
   42:  *
   43:  * @param recv_data The incoming pet action packet.
   44:  */
   45: void PetHandlers::HandlePetAction(WorldSession& session, WorldPacket& recv_data)
   46: {
   47:     ObjectGuid petGuid;
   48:     uint32 data;
   49:     ObjectGuid targetGuid;
   50:     float x, y, z;
   51:     recv_data >> petGuid;
   52:     recv_data >> data;
   53:     recv_data >> targetGuid;
   54:     recv_data >> x >> y >> z;
   55: 
   56:     uint32 spellid = UNIT_ACTION_BUTTON_ACTION(data);
   57:     uint8 flag = UNIT_ACTION_BUTTON_TYPE(data);             // delete = 0x07 CastSpell = C1
   58: 
   59:     DETAIL_LOG("HandlePetAction: %s flag is %u, spellid is %u, target %s.", petGuid.GetString().c_str(), uint32(flag), spellid, targetGuid.GetString().c_str());
   60: 
   61:     // used also for charmed creature/player
   62:     Unit* pet = session.GetPlayer()->GetMap()->GetUnit(petGuid);
   63:     if (!pet)
   64:     {
   65:         sLog.outError("HandlePetAction: %s not exist.", petGuid.GetString().c_str());
   66:         return;
   67:     }
   68: 
   69:     if (session.GetPlayer()->GetObjectGuid() != pet->GetCharmerOrOwnerGuid())
   70:     {
   71:         sLog.outError("HandlePetAction: %s isn't controlled by %s.", petGuid.GetString().c_str(), session.GetPlayer()->GetGuidStr().c_str());
   72:         return;
   73:     }
   74: 
   75:     if (!pet->IsAlive())
   76:     {
   77:         return;
   78:     }
   79: 
   80:     if (pet->GetTypeId() == TYPEID_PLAYER)
   81:     {
   82:         // controller player can only do melee attack
   83:         if (!(flag == ACT_COMMAND && spellid == COMMAND_ATTACK))
   84:         {
   85:             return;
   86:         }
   87:     }
   88:     else if (pet->IsPet())
   89:     {
   90:         // pet can have action bar disabled
   91:         if (((Pet*)pet)->GetModeFlags() & PET_MODE_DISABLE_ACTIONS)
   92:         {
   93:             return;
   94:         }
   95:     }
   96: 
   97:     CharmInfo* charmInfo = pet->GetCharmInfo();
   98:     if (!charmInfo)
   99:     {
  100:         sLog.outError("WorldSession::HandlePetAction: object (GUID: %u TypeId: %u) is considered pet-like but doesn't have a charminfo!", pet->GetGUIDLow(), pet->GetTypeId());
  101:         return;
  102:     }
  103: 
  104:     switch (flag)
  105:     {
  106:         case ACT_COMMAND:                                   // 0x07
  107:             switch (spellid)
  108:             {
  109:                 case COMMAND_STAY:                          // flat=1792  // STAY
  110:                 {
  111:                     pet->StopMoving();
  112:                     pet->AttackStop(true);
  113:                     pet->GetMotionMaster()->Clear();
  114:                     ((Pet*)pet)->SetStayPosition(true);
  115:                     ((Pet*)pet)->SetIsRetreating();
  116:                     ((Pet*)pet)->SetSpellOpener();
  117:                     charmInfo->SetCommandState(COMMAND_STAY);
  118:                     break;
  119:                 }
  120:                 case COMMAND_FOLLOW:                        // spellid=1792  // FOLLOW
  121:                 {
  122:                     pet->StopMoving();
  123:                     pet->AttackStop(true);
  124:                     pet->GetMotionMaster()->Clear();
  125:                     ((Pet*)pet)->SetStayPosition();
  126:                     ((Pet*)pet)->SetIsRetreating(true);
  127:                     ((Pet*)pet)->SetSpellOpener();
  128:                     charmInfo->SetCommandState(COMMAND_FOLLOW);
  129:                     break;
  130:                 }
  131:                 case COMMAND_ATTACK:                        // spellid=1792  // ATTACK
  132:                 {
  133:                     ((Pet*)pet)->SetIsRetreating();
  134:                     ((Pet*)pet)->SetSpellOpener();
  135: 
  136:                     Unit* targetUnit = targetGuid ? session.GetPlayer()->GetMap()->GetUnit(targetGuid) : NULL;
  137: 
  138:                     if (targetUnit && targetUnit != pet && targetUnit->IsTargetableForAttack() && targetUnit->isInAccessablePlaceFor((Creature*)pet))
  139:                     {
  140:                         session.GetPlayer()->SetInCombatState(true, targetUnit);
  141: 
  142:                         // This is true if pet has no target or has target but targets differs.
  143:                         if (pet->getVictim() != targetUnit)
  144:                         {
  145:                             pet->AttackStop();
  146:                             pet->GetMotionMaster()->Clear();
  147: 
  148:                             if (((Creature*)pet)->AI())
  149:                             {
  150:                                 ((Creature*)pet)->AI()->AttackStart(targetUnit);
  151:                                  // 10% chance to play special warlock pet attack talk, else growl
  152:                                 if (pet->IsPet() && ((Pet*)pet)->getPetType() == SUMMON_PET && roll_chance_i(10))
  153:                                 {
  154:                                     pet->SendPetTalk((uint32)PET_TALK_ATTACK);
  155:                                 }
  156: 
  157:                                 pet->SendPetAIReaction();
  158:                             }
  159:                             else
  160:                             {
  161:                                 pet->Attack(targetUnit, true);
  162:                             }
  163:                         }
  164:                     }
  165: 
  166:                     break;
  167:                 }
  168:                 case COMMAND_ABANDON:                       // abandon (hunter pet) or dismiss (summoned pet)
  169:                 {
  170:                     Creature* petC = (Creature*)pet;
  171:                     if (petC->IsPet())
  172:                     {
  173:                         Pet* p = (Pet*)petC;
  174:                         if (p->getPetType() == HUNTER_PET)
  175:                         {
  176:                             p->Unsummon(PET_SAVE_AS_DELETED, session.GetPlayer());
  177:                             return;
  178:                         }
  179:                         else
  180:                         {
  181:                             // dismissing a summoned pet is like killing them (this prevents returning a soulshard...)
  182:                             p->SetDeathState(CORPSE);
  183:                         }
  184:                     }
  185:                     else                                    // charmed
  186:                     {
  187:                         session.GetPlayer()->Uncharm();
  188:                     }
  189: 
  190:                     if (petC->IsTemporarySummon()) // special case when pet was temporary summon through DoSummonPossesed
  191:                     {
  192:                         petC->ForcedDespawn();
  193:                         return;
  194:                     }
  195: 
  196:                     ((Pet*)pet)->SetStayPosition();
  197:                     break;
  198:                 }
  199:                 default:
  200:                     sLog.outError("WORLD: unknown PET flag Action %i and spellid %i.", uint32(flag), spellid);
  201:             }
  202:             break;
  203:         case ACT_REACTION:                                  // 0x6
  204:             switch (spellid)
  205:             {
  206:                 case REACT_PASSIVE:                         // passive
  207:                 {
  208:                     pet->AttackStop(true);
  209:                     ((Pet*)pet)->SetSpellOpener();
  210:                 }
  211:                 // fall through
  212:                 case REACT_DEFENSIVE:                       // recovery
  213:                 case REACT_AGGRESSIVE:                      // activete
  214:                 {
  215:                     charmInfo->SetReactState(ReactStates(spellid));
  216:                     break;
  217:                 }
  218:             }
  219:             break;
  220:         case ACT_DISABLED:                                  // 0x81    spell (disabled), ignore
  221:         case ACT_PASSIVE:                                   // 0x01
  222:         case ACT_ENABLED:                                   // 0xC1    spell
  223:         {
  224:             ((Pet*)pet)->SetIsRetreating();
  225:             ((Pet*)pet)->SetSpellOpener();
  226: 
  227:             Unit* unit_target = targetGuid ? session.GetPlayer()->GetMap()->GetUnit(targetGuid) : NULL;
  228: 
  229:             // do not cast unknown spells
  230:             SpellEntry const* spellInfo = sSpellStore.LookupEntry(spellid);
  231:             if (!spellInfo)
  232:             {
  233:                 sLog.outError("WORLD: unknown PET spell id %i", spellid);
  234:                 return;
  235:             }
  236: 
  237:             if (pet->GetCharmInfo() && pet->GetCharmInfo()->GetGlobalCooldownMgr().HasGlobalCooldown(spellInfo))
  238:             {
  239:                 return;
  240:             }
  241: 
  242:             for (int i = 0; i < MAX_EFFECT_INDEX; ++i)
  243:             {
  244:                 SpellEffectEntry const* spellEffect = spellInfo->GetSpellEffect(SpellEffectIndex(i));
  245:                 if (!spellEffect)
  246:                 {
  247:                     continue;
  248:                 }
  249: 
  250:                 if (spellEffect->ImplicitTarget_0 == TARGET_ALL_ENEMY_IN_AREA
  251:                     || spellEffect->ImplicitTarget_0 == TARGET_ALL_ENEMY_IN_AREA_INSTANT
  252:                     || spellEffect->ImplicitTarget_0 == TARGET_ALL_ENEMY_IN_AREA_CHANNELED)
  253:                     return;
  254:             }
  255: 
  256:             // do not cast not learned spells
  257:             if (!pet->HasSpell(spellid) || IsPassiveSpell(spellInfo))
  258:             {
  259:                 return;
  260:             }
  261: 
  262:             session.GetPlayer()->SetInCombatState(true, unit_target);
  263: 
  264:             pet->GetMotionMaster()->ClearMovingLatches();
  265: 
  266:             Spell* spell = new Spell(pet, spellInfo, false);
  267: 
  268:             SpellCastResult result = spell->CheckPetCast(unit_target);
  269: 
  270:             const SpellRangeEntry* sRange = sSpellRangeStore.LookupEntry(spellInfo->RangeIndex);
  271: 
  272:             if (unit_target && !(InReach(*pet, *unit_target, sRange->RangeMax_0) && HasLineOfSight(*pet, *unit_target))
  273:                 && !(session.GetPlayer()->IsFriendlyTo(unit_target) || pet->HasAuraType(SPELL_AURA_MOD_POSSESS)))
  274:             {
  275:                 ((Pet*)pet)->SetSpellOpener(spellid, sRange->RangeMin_0, sRange->RangeMax_0);
  276:                 spell->finish(false);
  277:                 delete spell;
  278: 
  279:                 pet->AttackStop();
  280:                 pet->GetMotionMaster()->Clear();
  281: 
  282:                 ((Creature*)pet)->AI()->AttackStart(unit_target);
  283:                  // 10% chance to play special warlock pet attack talk, else growl
  284:                 if (pet->IsPet() && ((Pet*)pet)->getPetType() == SUMMON_PET && pet != unit_target && roll_chance_i(10))
  285:                 {
  286:                     pet->SendPetTalk((uint32)PET_TALK_ATTACK);
  287:                 }
  288: 
  289:                 pet->SendPetAIReaction();
  290: 
  291:                 return;
  292:             }
  293: 
  294:             // auto turn to target unless possessed
  295:             if (result == SPELL_FAILED_UNIT_NOT_INFRONT && !pet->HasAuraType(SPELL_AURA_MOD_POSSESS))
  296:             {
  297:                 if (unit_target)
  298:                 {
  299:                     pet->SetInFront(unit_target);
  300:                     if (unit_target->GetTypeId() == TYPEID_PLAYER)
  301:                     {
  302:                         pet->SendCreateUpdateToPlayer((Player*)unit_target);
  303:                     }
  304:                 }
  305:                 else if (Unit* unit_target2 = spell->m_targets.getUnitTarget())
  306:                 {
  307:                     pet->SetInFront(unit_target2);
  308:                     if (unit_target2->GetTypeId() == TYPEID_PLAYER)
  309:                     {
  310:                         pet->SendCreateUpdateToPlayer((Player*)unit_target2);
  311:                     }
  312:                 }
  313:                 if (Unit* powner = pet->GetCharmerOrOwner())
  314:                     if (powner->GetTypeId() == TYPEID_PLAYER)
  315:                     {
  316:                         pet->SendCreateUpdateToPlayer((Player*)powner);
  317:                     }
  318:                 result = SPELL_CAST_OK;
  319:             }
  320: 
  321:             if (result == SPELL_CAST_OK)
  322:             {
  323:                 ((Creature*)pet)->AddCreatureSpellCooldown(spellid);
  324: 
  325:                 unit_target = spell->m_targets.getUnitTarget();
  326: 
  327:                 ((Pet*)pet)->SetSpellOpener();
  328:                 spell->SpellStart(&(spell->m_targets));
  329:             }
  330:             else
  331:             {
  332:                 if (pet->HasAuraType(SPELL_AURA_MOD_POSSESS))
  333:                 {
  334:                     Spell::SendCastResult(session.GetPlayer(), spellInfo, 0, result);
  335:                 }
  336:                 else
  337:                 {
  338:                     Unit* owner = pet->GetCharmerOrOwner();
  339:                     if (owner && owner->GetTypeId() == TYPEID_PLAYER)
  340:                     {
  341:                         Spell::SendCastResult((Player*)owner, spellInfo, 0, result, true);
  342:                     }
  343:                 }
  344: 
  345:                 if (!((Creature*)pet)->HasSpellCooldown(spellid))
  346:                 {
  347:                     session.GetPlayer()->SendClearCooldown(spellid, pet);
  348:                 }
  349: 
  350:                 ((Pet*)pet)->SetSpellOpener();
  351:                 spell->finish(false);
  352:                 delete spell;
  353:             }
  354:             break;
  355:         }
  356:         default:
  357:             sLog.outError("WORLD: unknown PET flag Action %i and spellid %i.", uint32(flag), spellid);
  358:     }
  359: }
