  361: /**
  362:  * @brief Handles a request to stop the active pet attack.
  363:  *
  364:  * @param recv_data The incoming stop-attack packet.
  365:  */
  366: void PetHandlers::HandlePetStopAttack(WorldSession& session, WorldPacket& recv_data)
  367: {
  368:     DEBUG_LOG("WORLD: Received opcode CMSG_PET_STOP_ATTACK");
  369: 
  370:     ObjectGuid petGuid;
  371:     recv_data >> petGuid;
  372: 
  373:     Unit* pet = session.GetPlayer()->GetMap()->GetUnit(petGuid);    // pet or controlled creature/player
  374:     if (!pet)
  375:     {
  376:         sLog.outError("%s doesn't exist.", petGuid.GetString().c_str());
  377:         return;
  378:     }
  379: 
  380:     if (session.GetPlayer()->GetObjectGuid() != pet->GetCharmerOrOwnerGuid())
  381:     {
  382:         sLog.outError("HandlePetStopAttack: %s isn't charm/pet of %s.", petGuid.GetString().c_str(), session.GetPlayer()->GetGuidStr().c_str());
  383:         return;
  384:     }
  385: 
  386:     if (!pet->IsAlive())
  387:     {
  388:         return;
  389:     }
  390: 
  391:     pet->AttackStop();
  392: }
