  394: /**
  395:  * @brief Handles updates to the pet action bar layout and autocast states.
  396:  *
  397:  * @param recv_data The incoming pet set-action packet.
  398:  */
  399: void PetHandlers::HandlePetSetAction(WorldSession& session, WorldPacket& recv_data)
  400: {
  401:     DETAIL_LOG("HandlePetSetAction. CMSG_PET_SET_ACTION");
  402: 
  403:     ObjectGuid petGuid;
  404:     uint8  count;
  405: 
  406:     recv_data >> petGuid;
  407: 
  408:     Creature* pet = session.GetPlayer()->GetMap()->GetAnyTypeCreature(petGuid);
  409: 
  410:     if (!pet || (pet != session.GetPlayer()->GetPet() && pet != session.GetPlayer()->GetCharm()))
  411:     {
  412:         sLog.outError("HandlePetSetAction: Unknown pet or pet owner.");
  413:         return;
  414:     }
  415: 
  416:     // pet can have action bar disabled
  417:     if (pet->IsPet() && ((Pet*)pet)->GetModeFlags() & PET_MODE_DISABLE_ACTIONS)
  418:     {
  419:         return;
  420:     }
  421: 
  422:     CharmInfo* charmInfo = pet->GetCharmInfo();
  423:     if (!charmInfo)
  424:     {
  425:         sLog.outError("WorldSession::HandlePetSetAction: object (GUID: %u TypeId: %u) is considered pet-like but doesn't have a charminfo!", pet->GetGUIDLow(), pet->GetTypeId());
  426:         return;
  427:     }
  428: 
  429:     count = (recv_data.size() == 24) ? 2 : 1;
  430: 
  431:     uint32 position[2];
  432:     uint32 data[2];
  433:     bool move_command = false;
  434: 
  435:     for (uint8 i = 0; i < count; ++i)
  436:     {
  437:         recv_data >> position[i];
  438:         recv_data >> data[i];
  439: 
  440:         uint8 act_state = UNIT_ACTION_BUTTON_TYPE(data[i]);
  441: 
  442:         // ignore invalid position
  443:         if (position[i] >= MAX_UNIT_ACTION_BAR_INDEX)
  444:         {
  445:             return;
  446:         }
  447: 
  448:         // in the normal case, command and reaction buttons can only be moved, not removed
  449:         // at moving count ==2, at removing count == 1
  450:         // ignore attempt to remove command|reaction buttons (not possible at normal case)
  451:         if (act_state == ACT_COMMAND || act_state == ACT_REACTION)
  452:         {
  453:             if (count == 1)
  454:             {
  455:                 return;
  456:             }
  457: 
  458:             move_command = true;
  459:         }
  460:     }
  461: 
  462:     // check swap (at command->spell swap client remove spell first in another packet, so check only command move correctness)
  463:     if (move_command)
  464:     {
  465:         uint8 act_state_0 = UNIT_ACTION_BUTTON_TYPE(data[0]);
  466:         if (act_state_0 == ACT_COMMAND || act_state_0 == ACT_REACTION)
  467:         {
  468:             uint32 spell_id_0 = UNIT_ACTION_BUTTON_ACTION(data[0]);
  469:             UnitActionBarEntry const* actionEntry_1 = charmInfo->GetActionBarEntry(position[1]);
  470:             if (!actionEntry_1 || spell_id_0 != actionEntry_1->GetAction() ||
  471:                     act_state_0 != actionEntry_1->GetType())
  472:                 return;
  473:         }
  474: 
  475:         uint8 act_state_1 = UNIT_ACTION_BUTTON_TYPE(data[1]);
  476:         if (act_state_1 == ACT_COMMAND || act_state_1 == ACT_REACTION)
  477:         {
  478:             uint32 spell_id_1 = UNIT_ACTION_BUTTON_ACTION(data[1]);
  479:             UnitActionBarEntry const* actionEntry_0 = charmInfo->GetActionBarEntry(position[0]);
  480:             if (!actionEntry_0 || spell_id_1 != actionEntry_0->GetAction() ||
  481:                     act_state_1 != actionEntry_0->GetType())
  482:                 return;
  483:         }
  484:     }
  485: 
  486:     for (uint8 i = 0; i < count; ++i)
  487:     {
  488:         uint32 spell_id = UNIT_ACTION_BUTTON_ACTION(data[i]);
  489:         uint8 act_state = UNIT_ACTION_BUTTON_TYPE(data[i]);
  490: 
  491:         DETAIL_LOG("Player %s has changed pet spell action. Position: %u, Spell: %u, State: 0x%X", session.GetPlayer()->GetName(), position[i], spell_id, uint32(act_state));
  492: 
  493:         // if it's act for spell (en/disable/cast) and there is a spell given (0 = remove spell) which pet doesn't know, don't add
  494:         if (!((act_state == ACT_ENABLED || act_state == ACT_DISABLED || act_state == ACT_PASSIVE) && spell_id && !pet->HasSpell(spell_id)))
  495:         {
  496:             // sign for autocast
  497:             if (act_state == ACT_ENABLED && spell_id)
  498:             {
  499:                 if (pet->IsCharmed())
  500:                 {
  501:                     charmInfo->ToggleCreatureAutocast(spell_id, true);
  502:                 }
  503:                 else
  504:                 {
  505:                     ((Pet*)pet)->ToggleAutocast(spell_id, true);
  506:                 }
  507:             }
  508:             // sign for no/turn off autocast
  509:             else if (act_state == ACT_DISABLED && spell_id)
  510:             {
  511:                 if (pet->IsCharmed())
  512:                 {
  513:                     charmInfo->ToggleCreatureAutocast(spell_id, false);
  514:                 }
  515:                 else
  516:                 {
  517:                     ((Pet*)pet)->ToggleAutocast(spell_id, false);
  518:                 }
  519:             }
  520: 
  521:             charmInfo->SetActionBar(position[i], spell_id, ActiveStates(act_state));
  522:         }
  523:     }
  524: }
