  526: /**
  527:  * @brief Handles pet spell autocast toggles.
  528:  *
  529:  * @param recvPacket The incoming pet autocast packet.
  530:  */
  531: void PetHandlers::HandlePetSpellAutocast(WorldSession& session, WorldPacket& recvPacket)
  532: {
  533:     DETAIL_LOG("CMSG_PET_SPELL_AUTOCAST");
  534: 
  535:     ObjectGuid guid;
  536:     uint32 spellid;
  537:     uint8  state;                                           // 1 for on, 0 for off
  538:     recvPacket >> guid >> spellid >> state;
  539: 
  540:     Creature* pet = session.GetPlayer()->GetMap()->GetAnyTypeCreature(guid);
  541:     if (!pet || (guid != session.GetPlayer()->GetPetGuid() && guid != session.GetPlayer()->GetCharmGuid()))
  542:     {
  543:         sLog.outError("HandlePetSpellAutocastOpcode. %s isn't pet of %s .", guid.GetString().c_str(), session.GetPlayer()->GetGuidStr().c_str());
  544:         return;
  545:     }
  546: 
  547:     // do not add not learned spells/ passive spells
  548:     if (!pet->HasSpell(spellid) || IsPassiveSpell(spellid))
  549:     {
  550:         return;
  551:     }
  552: 
  553:     CharmInfo* charmInfo = pet->GetCharmInfo();
  554:     if (!charmInfo)
  555:     {
  556:         sLog.outError("WorldSession::HandlePetSpellAutocastOpcod: %s is considered pet-like but doesn't have a charminfo!", guid.GetString().c_str());
  557:         return;
  558:     }
  559: 
